def combinationSum4(nums: List[int], target: int) -> int:
    def dfs(rem):
        if rem == 0:
            return 1
        if rem < 0:
            return 0
        total = 0
        for num in nums:
            total += dfs(rem - num)
        return total
    return dfs(target)

